function validate([maze, start, destination]) {
  if (!Array.isArray(maze) || maze.length < 1 || maze.length > 100) return 'maze needs 1 to 100 rows.';
  const cols = Array.isArray(maze[0]) ? maze[0].length : 0;
  if (cols < 1 || cols > 100) return 'maze needs 1 to 100 columns.';
  for (const row of maze) {
    if (!Array.isArray(row) || row.length !== cols) return 'Every row of maze must have the same length.';
    if (row.some(v => v !== 0 && v !== 1)) return 'Each cell of maze is 0 or 1.';
  }
  const inside = p => Array.isArray(p) && p.length === 2 && Number.isInteger(p[0]) && Number.isInteger(p[1]) && p[0] >= 0 && p[0] < maze.length && p[1] >= 0 && p[1] < cols;
  if (!inside(start)) return 'start must be [row, col] inside the maze.';
  if (!inside(destination)) return 'destination must be [row, col] inside the maze.';
  if (maze[start[0]][start[1]] !== 0) return 'start must be an open cell.';
  if (maze[destination[0]][destination[1]] !== 0) return 'destination must be an open cell.';
  if (start[0] === destination[0] && start[1] === destination[1]) return 'start and destination must be different cells.';
  return null;
}

