function hasPath(maze, start, destination) {
  // Grow the set of resting cells until nothing new appears (a fixpoint), then look the destination up.
  const m = maze.length, n = maze[0].length;
  const resting = new Set([start[0] * n + start[1]]);
  let grew = true;
  while (grew) {
    grew = false;
    for (const cell of [...resting]) {
      const r0 = Math.floor(cell / n), c0 = cell % n;
      let j = c0; while (j + 1 < n && maze[r0][j + 1] === 0) j++;
      const right = r0 * n + j;
      j = c0; while (j - 1 >= 0 && maze[r0][j - 1] === 0) j--;
      const left = r0 * n + j;
      let i = r0; while (i + 1 < m && maze[i + 1][c0] === 0) i++;
      const down = i * n + c0;
      i = r0; while (i - 1 >= 0 && maze[i - 1][c0] === 0) i--;
      const up = i * n + c0;
      for (const next of [right, left, down, up]) if (!resting.has(next)) { resting.add(next); grew = true; }
    }
  }
  return resting.has(destination[0] * n + destination[1]);
}

