function generate(rand, size) {
  for (;;) {
    const rows = size === 'large' ? 80 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 6);
    const cols = size === 'large' ? 80 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 6);
    const density = size === 'large' ? 0.1 + rand() * 0.25 : rand() * 0.45;
    const maze = Array.from({ length: rows }, () => Array.from({ length: cols }, () => (rand() < density ? 1 : 0)));
    const open = [];
    for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) if (maze[r][c] === 0) open.push([r, c]);
    if (open.length < 2) continue;
    const start = open[Math.floor(rand() * open.length)];
    // Find every resting cell reachable from start, so half the inputs can aim at one (answer true).
    const seen = new Set([start[0] * cols + start[1]]);
    const stops = [];
    const queue = [start];
    for (let q = 0; q < queue.length; q++) {
      const [r, c] = queue[q];
      for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        let i = r, j = c;
        while (i + dr >= 0 && i + dr < rows && j + dc >= 0 && j + dc < cols && maze[i + dr][j + dc] === 0) { i += dr; j += dc; }
        if (!seen.has(i * cols + j)) { seen.add(i * cols + j); stops.push([i, j]); queue.push([i, j]); }
      }
    }
    const others = open.filter(([r, c]) => r !== start[0] || c !== start[1]);
    const pool = rand() < 0.5 && stops.length ? stops : others;
    const destination = pool[Math.floor(rand() * pool.length)];
    return [maze, [start[0], start[1]], [destination[0], destination[1]]];
  }
}
